init
	load_program("ChargeStation")

include "widgets.xc"
;include "ChargeStation.main.xc"

var $screen = screen(0,0)
var $screen2 = screen(1,1)

tick
	$screen.blank(black)
	$screen2.blank(black)

	$screen.text_size(2)
	$screen2.text_size(2)

	var $bat1 = input_number(2,2)
	var $bat2 = input_number(3,2)
	var $bat3 = input_number(6,2)
	var $bat4 = input_number(7,2)
	var $bat5 = input_number(8,2)
	var $bat6 = input_number(9,2)
	var $bat7 = input_number(10,2)
	var $bat8 = input_number(11,2)

	var $BatteryCharge = ($bat1+$bat2+$bat3+$bat4+$bat5+$bat6+$bat7+$bat8)/8
	@drawBattery($screen, $BatteryCharge, 4, 13, 80, 30, text(" {0}%",$BatteryCharge*100))
	@drawBattery($screen2, $BatteryCharge, 4, 13, 80, 30, text(" {0}%",$BatteryCharge*100))

;init
;	load_program("ChargeStation")

var $screendash = screen("DashboardMain",1)
var $screentanks = screen("DashboardMain",2)
var $screenbuttons = screen("DashboardMain",3)
var $screenBattery = screen("DashboardMain",4)

var $buttonstate1 = 0
var $buttonstate2 = 0
var $buttonstate3 = 1
var $buttonstate4 = 1

var $buttoncolor1 = color(115,10,10)
var $buttoncolor2 = color(115,10,10)
var $buttoncolor3 = green
var $buttoncolor4 = green



include "widgets.xc"

tick
	$screenbuttons.blank(0)
	$screenBattery.blank(0)
	var $Battery = input_number("BatteryBase",2)
	@drawBattery($screenBattery, green, $Battery, 4, 4, 80, 24, text("HV {0}%",$Battery*100))

	$screentanks.blank(0)
	$screendash.blank(0)
	var $tank_O2 = input_number("tank_O2",0)
	var $colorO2 = cyan
	var $tank_H2 = input_number("tank_H2",0)
	var $colorH2 = yellow
	var $tank_H2O = input_number("tank_H2O",0)
	var $colorH2O = blue
	@drawTank($screentanks, $colorO2, $tank_O2, 20, 9, 200, 20, text("O2 {0}%",$tank_O2*100))
	@drawTank($screentanks, $colorH2, $tank_H2, 20, 35, 200, 20, text("H2 {0}%",$tank_H2*100))
	@drawTank($screentanks, $colorH2O, $tank_H2O, 20, 61, 200, 20, text("H2O {0}%",$tank_H2O*100))
	var $Container = input_text("container",0)
	@containeritems(2,7,color(2,2,30),$screendash,$Container)

update


	@crusherbutton($screenbuttons,40,40,30)
	@electrolizerbutton($screenbuttons,120,40,30)
	@lightbutton($screenbuttons,40,120,30)
	@anchorbutton($screenbuttons,120,120,30)


	output_number("crusher",0,$buttonstate2)
	output_number("crusherConveyor",0,$buttonstate2)
	output_number("electrolizer",0,$buttonstate1)
	output_number("Lamp1",0,$buttonstate3)
	output_number("Lamp2",0,$buttonstate3)
	output_number("Lamp3",0,$buttonstate3)
	output_number("Lamp4",0,$buttonstate3)
	output_number("Lamp5",0,$buttonstate3)
	output_number("Lamp6",0,$buttonstate3)
	output_number("Anchor",0,$buttonstate4)
